      "ア": "D. ラベルジュによる実験の参加者は、単語中央の文字を特定する第1課題及び単語全体をその意味により分類する第2課題を行った。課題遂行中に、単語内のいろいろな位置に提示されたプローブ刺激への反応時間を計測したところ、第1課題では、プローブ刺激の位置に依存せずに反応時間が等しくなった一方で、第2課題では、単語中央に提示されたプローブ刺激への反応時間が遅くなった。ラベルジュは、注意はスポットライトのように機能し、課題内容にかかわらず注意の範囲は固定されていると主張した。",
      "イ": "M.I. ポズナーらは、外発的注意を向けさせる手がかりを提示した後に標的を提示し、標的検出にかかる反応時間を計測した。手がかりと標的との時間間隔が300ミリ秒を超えると、両者の位置が一致している条件における反応時間よりも、一致していない条件における反応時間の方が短くなった。この現象は復帰の抑制と呼ばれており、内発的注意を向けさせる手がかりを提示した場合には生じないという報告がある。",
      "ウ": "J. E. レイモンドらは、高速系列視覚提示法により、いろいろな文字を同じ位置に次々と提示した。実験参加者の課題は、この文字系列の中に埋め込まれた第一標的と第二標的を検出することであった。実験の結果、第一標的の提示直後から約500ミリ秒にわたって、第二標的の有無の判断が容易になることが分かった。そこでレイモンドらは、第一標的検出後に「注意の瞬き」が生じ、その結果として文字処理が促進されたと考えた。",
      "エ": "R.A. レンシンクらは、情景認識における注意の影響を検討するために、フリッカー法により、情景画像Aとそれを部分的に変化させた情景画像Bを交互に提示し、実験参加者に画像の変化箇所を報告させた。すると、画像変化の発見までに時間が掛かるという 「変化の見落とし」が生じた。しかし、AとBの間に空白の画面を短時間挟み、光の過渡的変化を手がかりにした検出を可能にすると、画像の変化箇所は容易に発見できるようになった。",
