    "question": "次は、共感性に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\nただし、Bには、㋐又は㋑のいずれかが入る。\n\n共感性とは、「他者の情動状態を知覚することに伴って生起する代理的な情動反応」を指す。M. L. ホフマンは他者の苦悩や痛みへの共感を共感的苦痛と呼んだが、このときの感情反応には、個人的苦痛と［A］の二つがある。両者は、利己的行動と利他的行動との関連において、［B］。また、共感性と類似ないし共感性に包含される概念に［C］がある。［C］は、他者に対する悲しみや心配から成る感情反応である。\n\nホフマン（2008）は共感の喚起に関する様式を五つに整理している。彼によると、五つのうち「動作模倣（mimicry）」、「［D］」、「［E］」の三つは自動的で前言語的なものであり、共感性の基礎と考えられている。\n\nBの候補\n㋐：個人的苦痛は利己的行動を動機づけ、［A］は利他的行動を動機づける\n㋑：個人的苦痛は利他的行動を動機づけ、［A］は利己的行動を動機づける\n\n*1 条件づけ（conditioning）\n*2 視点取得（perspective taking）\n*3 直接的連合（direct association）\n*4 言語を媒介とした連合（verbally mediated association）\n\n各選択肢はA、B、C、D、Eの順。",
