    "question": "次は、ある実験手続に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n調整法によって、ミュラー＝リヤー錯視における錯視量を測定する実験を計画している。調整法では、上昇試行と下降試行で測定結果が異なることが多い。また、外向図形と内向図形を並べる際の左右の配置も測定結果に影響する可能性がある。そこで、次のような試行の順序で実験を実施することを考えた（「右」、「左」は内向図形の位置を表すものとする。）。\n\n右・上昇、左・下降、左・上昇、右・下降、左・上昇、右・下降、右・上昇、左・下降\n\nしかし、この実施順では、上昇試行と下降試行の出現が規則的になっているため、順序効果を［A］できない。また、［B］試行が常に［C］試行に先行するので、平均的には［C］試行の方が測定結果が安定するといった練習効果が生じるかもしれない。\n\nそこで、次のような修正案が提示された。\n\n右・上昇、左・下降、左・上昇、右・下降、左・下降、右・上昇、右・下降、左・上昇\n\nこの方式にすることで、上昇試行も下降試行も［D］を等しくできるため、順序効果は同等となることが期待できる。\n\nしかし、この方式であっても、順序効果が時間に対して［E］である場合には、異なる種類の試行の間で順序効果が等しくならない。この問題に対処する方法の一つには、ある実験参加者には元の系列を、別の実験参加者には次のような裏返しの系列を実施することが考えられる。\n\n左・下降、右・上昇、右・下降、左・上昇、右・上昇、左・下降、左・上昇、右・下降\n\n各選択肢はA、B、C、D、Eの順。",
