    "difficulty": 3,
    "question": "次は、心理学研究に用いられる観察法に関する記述であるが、A～Fに当てはまるものの組合せとして最も妥当なのはどれか。\n\n人間や動物の行動を自然な状況や実験的な状況の下で観察、記録、分析し、行動の質的・量的特徴や行動の法則性を解明する方法を、観察法と呼ぶ。実証研究に役立つデータを得るために、心理学をはじめとする諸科学では、様々な観察の手続が考案されてきた。観察が一面的にならないようにする手法として、関心対象の事象が生じるかどうか、どのように生じるかを一定の時間間隔で記録する［A］、関心対象の事象が生じやすそうな場面や状況を選んで集中的に観察を行う［B］、関心対象の事象を前もって特定しておき、それが生じたときに、その前後の出来事とともに記録していく［C］などが知られている。\n\n研究目的と関心対象がはっきりしているときには、観察を枠付けるカテゴリーや、その属性を評定する尺度を準備した上で、対象の諸側面を記録する［D］がなされる場合がある。また、明確な仮説があり、観察の場の条件が統制できるような場合には、その条件と関心対象の行動との関係を検証するために、［E］が行われることもある。観察の目的や仮説を知らない独立の観察者を使って、観察にゆがみを生じさせない工夫が行われることもまれではない。\n\n以上のような工夫は、観察の焦点が決まっている場合に、観察をより客観的にしていく点で特に有効であるが、近年では、関心対象の現象について幅広い文脈との関連を見いだしながら新たな仮説を生成していく方向においても、観察法が見直されている。研究対象に対して操作を加えず、日常的な場面をそのまま観察する方法を［F］と呼ぶ。\n\n各選択肢はA、B、C、D、E、Fの順。",
