    "difficulty": 3,
    "question": "次は、回帰分析に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\nただし、Bには、㋐又は㋑のいずれかが入る。\n\nある二つの説明変数 x₁、x₂ を用いて目的変数 y を説明する重回帰モデル\n\ny = β₀ + β₁x₁ + β₂x₂ + ε\n\nを考える。ここで、パラメータ β₀、β₁、β₂ は推定する切片及び偏回帰係数であり、εは予測誤差である。さらに、それらパラメータと説明変数 x₁、x₂ を用いて予測値 ŷ を ŷ = β₀ + β₁x₁ + β₂x₂ で定義する。このとき、予測誤差 ε は y − ŷ と表され、説明変数と予測誤差は［A］ある。n個の観測に基づく重回帰分析を実行する場合、i番目の観測データ（i = 1, 2, …, n）の目的変数の値を yᵢ、その予測値を ŷᵢ と表すとすると、［B］を最小にするように β₀、β₁、β₂ を推定する。\n\n一般に、推定されたパラメータのうち偏回帰係数 β₂ は、［C］が目的変数 y に与える影響として解釈できる。ただし、x₁ と x₂ の相関が非常に高い場合に、推定される β₁、β₂ の値が不安定になるという［D］の問題が生じることがある。また、モデルによる予測の正確さを表す指標として重相関係数があり、これは y と［E］との相関係数である。\n\nBの候補\n㋐：(y₁ − ŷ₁)² + (y₂ − ŷ₂)² + … + (yₙ − ŷₙ)²\n㋑：(y₁ − ŷ₁) + (y₂ − ŷ₂) + … + (yₙ − ŷₙ)\n\n各選択肢はA、B、C、D、Eの順。",
