      "イ": "最小二乗法では、正負が打ち消し合う残差の和ではなく、各残差の平方の和を最小にする。説明変数間の相関が高いため係数が不安定になるのは多重共線性である。",
      "ウ": "切片を含む最小二乗法で予測誤差の平方和を最小にすると、残差は各説明変数と無相関になる。ほかの説明変数を固定した効果が偏回帰係数であり、強い説明変数間の相関が多重共線性、観測と予測の相関が重相関係数に当たる。",
      "エ": "無相関と平方和の組合せは妥当である。偏回帰係数はほかの説明変数を一定とした効果を表し、説明変数同士の強い相関は分散不均一性ではない。",
      "オ": "他の説明変数の値を一定とした効果と予測値との相関は妥当である。残差の平方和を最小にする必要があり、説明変数間の高い相関は多重共線性をもたらす。"
