    "question": "我が国の救貧施策の歴史に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\nA　明治時代に初めて成立した貧困者に対する一般的救済法は、明治7（1874）年に制定された恤救規則である。誰の助けも期待できない困窮者を無告の窮民として公費による救済を行ったが、その他の者の救済は、人民相互の情宜として家族や親族、隣人などによる相互扶助によるべきとした。\nB　昭和4（1929）年に制定された救護法は、米国の株価の大暴落に端を発した大恐慌の影響等による失業者数の増大を背景に、国の救貧制度の拡充を求める要望が高まる中、制定された。権利としての最低生活保障が確立され、要救護者による保護請求権が認められた。\nC　第二次世界大戦後に制定された日本国憲法の理念の下に昭和25（1950）年に現行の生活保護法が制定された。その後の改正を経て、現在、保護の基準は厚生労働大臣が定め、保護の実施機関は都道府県知事、市長及び福祉事務所を管理する町村長とされている。\nD　平成25（2013）年に制定された生活困窮者自立支援法は、現に生活保護を受給している者のうち、就労の可能性のある者を対象として、自立に向けた相談支援等を行うために制定された。公共職業安定所に相談支援員が配置され、家計相談や就労相談への支援を行うとされた。",
