    "difficulty": 3,
    "question": "次は、量的な内容分析に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n人文・社会科学研究において、マス・コミュニケーションを実証的に分析する手法として、量的な内容分析が古くから用いられてきた。量的な内容分析とは、新聞、雑誌、テレビ等の主にマスメディアが発する情報やメッセージの特性を、体系的、客観的に分析する手法を指す。量的な内容分析は米国における［A］研究に端を発し、現在ではマス・コミュニケーション研究のみならず、社会学、心理学、政治学、文化人類学、文学など多くの分野で用いられている。\n\nB. ベレルソンは、量的な内容分析の必要条件として次の四つを挙げている。第一に、分析対象が明示的な内容のみであること（原則として、隠れた意図や内容が引き起こす可能性のある反応は扱わない）。第二に、分析が客観的であり、分析者が異なっても同じ結果が得られること。第三に、分析が体系的であること（研究者の仮説に都合のよい部分だけを取り出してはいけない）。第四に、分析結果が数量的に把握できること。以上の点から、量的な内容分析は分析結果の［B］を重視したアプローチであることが示唆される。\n\n量的な内容分析を行う際には、分析対象の選定とサンプリングを行った上で、分析単位を決定し、変数とカテゴリーを定義する。例えば、「テレビCMに描かれる外国人像」を分析するとして、外国人が登場するCMを対象に、登場人物という分析単位に関して「性別」のような変数を設定し、「男性」、「女性」及び「その他」といったカテゴリーを用意する。これを踏まえて、変数とカテゴリーを記入したコーディング・シートを作成し、分析の作業のマニュアル化を行う。分析の作業量は膨大なので、通常は、複数のコーダー（作業従事者）が分類作業を行い、結果が一致するかどうかを確かめて［C］の確認を行う。\n\n量的な内容分析では伝統的に、人の手によるコーディング作業が行われてきたが、近年は、コンピュータを用いた大規模なデータ解析手法が急速に普及している。テキストマイニングとは、文章やメッセージなど人間が記述したテキストデータに対し、統計学や自然言語処理技術を活用して傾向性や変数同士の関連などの情報を引き出す手法の総称である。学術研究に加えて、アンケートの［D］やコールセンターへの問合せ内容、SNSの投稿といった、大量のテキストデータから顧客の意見や市場ニーズ、潜在的な課題などを把握するために導入が進んでいる。\n\n各選択肢はA、B、C、Dの順。",
