    "question": "次の記述のA～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\nF. I. M. クレイクとE. タルヴィング（1975）の実験の一つでは、アルファベットから成る単語を一語ずつ短時間（200ミリ秒）提示した。単語を提示する前にあらかじめ、実験参加者にはその単語についての質問をしておいた。質問には三つの種類があった。文字の形態処理を求めるもの（「この単語は大文字で書かれていますか」など）、音韻処理を求めるもの（「この単語はweightという単語と韻を踏みますか」など）、意味処理を求めるもの（「この単語は魚の一種を表しますか」など）であった。全ての単語について提示と質問への回答が終わった後、参加者には、単語の再認テストへの回答が求められた。参加者はテストがあることを事前には知らなかった。このような状況における学習を［A］という。\n\n実験の結果、形態条件よりも音韻条件、音韻条件よりも意味条件で、再認テストの成績が高かった。また、質問への回答に要する時間（反応時間）は、形態条件よりも音韻条件、音韻条件よりも意味条件で、長く掛かった。この結果は、処理水準（levels of processing）の観点から説明された。単語の情報処理過程は、文字の形態の認識から音韻処理、さらに、意味処理といったように何段階かの処理過程を経て進む。処理水準モデルでは、記憶痕跡の強さは情報処理の深さに応じて決まると仮定する。これを当てはめて考えると、形態条件よりも音韻条件、音韻条件よりも意味条件において処理が［B］ために、この順に再認成績が高くなったと説明できる。質問への回答に要する時間がこの順に長くなったことは、この間に［C］が行われたためと解釈される。\n\n当初の理論からは予想外の結果として、質問への回答が「はい」である場合に「いいえ」である場合よりも再認成績が高いことが見いだされた。このことは［D］の概念の導入によって説明された。\n\n各選択肢はA、B、C、Dの順。",
