    "question": "「性的マイノリティ」とされる児童生徒の支援に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\nA　文部科学省では、性同一性障害や性的指向・性自認に係る児童生徒に対するいじめを防止するため、いじめ防止対策推進法に基づく「いじめの防止等のための基本的な方針」を平成29年に改定し、「性同一性障害や性的指向・性自認について、教職員への正しい理解の促進や、学校として必要な対応について周知する」ことが追記された。\nB　「生徒指導提要」* において、「性的マイノリティ」とされる児童生徒の支援は、専門的知見を有する医療機関が主体となって行うこととされている。医療機関に対しては、当事者である児童生徒や保護者の同意が得られない場合でも、学校の判断に基づいて、当事者の個人情報も含めた詳細な情報共有を行うことが推奨されている。\nC　「生徒指導提要」において、「性的マイノリティ」とされる児童生徒の支援は、当該児童生徒が医療機関を受診して性同一性障害の診断がなされていることが前提とされている。また、「性的マイノリティ」とされる児童生徒が有する違和感は、成長に伴い増していくとされているため、児童生徒の学年が上がるにつれて慎重な支援が必要であるとされている。\nD　「生徒指導提要」において、「性的マイノリティ」とされる児童生徒に対する支援として、指導要録の記載については学齢簿の記載に基づき行いつつ、卒業後、法に基づく戸籍上の性別の変更等を行った者から卒業証明書等の発行を求められた場合、戸籍を確認した上で、当該者が不利益を被らないよう適切に対応することとされている。\n\n*「生徒指導提要」（令和4年12月改訂）",
