      "ウ": "言語音の知覚は、カテゴリー知覚の様式のもとで行われる。日本語圏で育つ子どもは、生後半年時点では、英語圏で育つ子どもと同じくらいに、英語の“l”と“r”の音素を区別することが可能であるが、成人した日本語話者の多くは、この区別が難しい。これは、子どもが自分の母語の音素カテゴリーを構築し、母語の音素に対する弁別力を高めると同時に、自分の母語では区別しない音素を弁別する能力を失っていくためである。",
