      "ウ": "「授業」とは、学校その他の教育機関の責任において、その管理下で教育を担任する者が学習者に対して実施する教育活動を指す。講義や実習のほかに、ホームルーム活動やクラブ活動、学校行事等もこれに該当する。入学志願者に対する学校説明会、オープンキャンパスでの模擬授業等はこれに該当しない。",
      "エ": "「必要と認められる限度」とは、授業の内容や進め方等とは関係なく、著作物の複製等を行うことの必要性が客観的に説明できる絶対的基準を指す。授業担当者が独自に購入した算数のドリルを担当するクラス以外の児童分を含めて複製することや、社会科の資料集の写真を10年分保存して使用できるよう製本化することは、一般に必要と認められる限度を超えないものとされる。",
      "オ": "「複製」とは、印刷、写真、複写、録音、録画により、既存の著作物の全部を有形的に再製することを指す。コピー機を使用して別の用紙にコピーすることや、スキャンしてPDFに変換することがこれに該当する。黒板への文学作品の板書や絵画の模写、紙粘土による彫刻の模造は、これに該当しない。"
