    "question": "我が国における情報教育に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\nA　平成29年改訂の小学校学習指導要領では、児童の発達の段階を考慮し、総合的な学習の時間内において、言語能力、情報活用能力、問題発見・解決能力等の学習の基盤となる資質・能力を育成することとされた。これは、必要な論理的思考力を身に付けることを目的としているため、一般には、児童が実際にプログラミングを体験することなどは想定されていない。\nB　生成AIは、教育分野においても様々な利活用が期待されており、文部科学省では、パイロット的な取組として、平成30年から、教育活動や校務において生成AIの活用に取り組む「生成AIパイロット校」を指定している。一方、生成AIには、誤った情報を出力してしまう「シンギュラリティ」や、人間の判断や意思決定において自動化されたシステムや技術に過度に依存してしまう 「正常化バイアス」のリスクが指摘されている。\nC　令和4年に実施されたPISA調査によると、SNSやデジタルゲームに費やす時間が3時間以上の生徒の割合は、我が国はOECD平均を下回っており、また、生徒の情報モラルについては、我が国はOECD諸国と比較すると高いことが示された。PISA調査結果を踏まえ、文部科学省は、GIGAスクール構想の推進と情報教育の更なる充実を図っている。\nD　平成30年改訂の高等学校学習指導要領に基づき、令和4年度から、高等学校においては共通必履修科目「情報Ⅰ」が新設され、全ての生徒が、プログラミングやネットワーク、データベースの基礎等について学習することとなった。また、大学入学共通テストでは、令和7年1月から「情報」が出題教科に追加され、高等学校卒業程度認定試験では、令和8年度試験から「情報」が試験科目に導入されることとなった。",
